// Project creation in browser memory only; no backend persistence.
const originalTaskCreate=$('#create').onclick;$('#create').innerHTML=icon('plus')+'新建';
function createProject(after){open('新建项目','PROJECT / 创建页内项目','<form id="projectform"><div class="formrow"><label for="projectname">项目名称 *</label><input id="projectname" required maxlength="80" placeholder="例如：客户 E 联合验证"></div><div class="formrow"><label for="projectgoal">目标 / 预期成果</label><input id="projectgoal" maxlength="240" placeholder="可以暂不填写"></div><div class="formrow"><label for="projectpartner">客户或合作伙伴</label><input id="projectpartner" maxlength="100" placeholder="待补充"></div><div class="formrow"><label for="projectstage">初始阶段</label><select id="projectstage"><option value="0">待规划</option><option value="1">接触</option><option value="2">需求</option><option value="3">方案</option><option value="4">验证</option><option value="5">复盘</option></select></div><p class="notice">仅创建当前页面的项目，不执行任务、不写入磁盘。刷新后恢复；没有交付项时显示“待规划”，不生成虚假进度。</p><button class="btn primary">创建页内项目</button></form>');$('#projectform').onsubmit=e=>{e.preventDefault();const raw=$('#projectname').value.trim();if(!raw)return;const esc=s=>s.replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));if(projects.some(p=>(p.rawName||p.name)===raw)){toast('已有同名项目，请查看现有项目或修改名称');return}const p={id:'new-'+Date.now(),name:esc(raw),rawName:raw,goal:$('#projectgoal').value,partner:esc($('#projectpartner').value.trim()||'伙伴待补'),done:0,total:0,docs:0,tasks:0,color:'#6488d6',bg:'#edf2ff',icon:'project',stage:Number($('#projectstage').value),start:0,duration:0,block:0};projects.push(p);graphNodes.push({id:'p:'+p.id,label:raw,type:'project',sub:'新建 · 待规划',x:480,y:850});const opt=document.createElement('option');opt.value='p:'+p.id;opt.textContent=raw;$('#projectfocus').append(opt);close();if(after)after(p);else{show('projects');renderProjects('portfolio')}toast('已创建页内项目；尚未持久化。')}}
$('#create').onclick=()=>{open('新建','CREATE / 选择对象','<div class="modalactions"><button class="btn primary" id="chooseproject">新建项目</button><button class="btn" id="choosetask">新建任务</button><button class="btn" id="chooseintake">从材料整理 / Agent 建议</button></div><p>项目组织目标、伙伴与交付；任务记录具体行动；材料录入可以建议关联已有项目或创建新项目。</p>');$('#chooseproject').onclick=()=>createProject();$('#choosetask').onclick=originalTaskCreate;$('#chooseintake').onclick=intake};
const pjButton=document.createElement('button');pjButton.className='btn primary';pjButton.textContent='＋ 新建项目';pjButton.onclick=()=>createProject();$('#projects .toolbar').append(pjButton);
const cardBeforeV7=card;card=function(p){if(p.total)return cardBeforeV7(p);return '<button class="project surface" data-project="'+p.id+'"><div class="projecttop"><span class="symbol">'+icon('project')+'</span><span class="chip">待规划</span></div><h3>'+p.name+'</h3><p>'+p.partner+'</p><p>尚无交付项 · 尚无任务</p></button>'};
const detailBeforeV7=projectDetail;projectDetail=function(id){const p=projects.find(x=>x.id===id);if(p.total){detailBeforeV7(id);return}open(p.rawName,'PROJECT / 页内新项目','<p>待规划 · 尚无交付项，暂无完成比例。</p><div class="proof" id="newprojectgoal"></div><div class="modalactions"><button class="btn" id="newprojectgraph">在画布查看</button><button class="btn" id="newprojectintake">录入项目资料</button></div><p class="notice">当前为页内演示，刷新会丢失；真实任务与项目编辑服务待接入。</p>');$('#newprojectgoal').textContent=p.goal||'目标待补充';$('#newprojectgraph').onclick=()=>launchSpace('p:'+id);$('#newprojectintake').onclick=()=>{batch.project=id;intake()}};
const intakeBeforeV7=intake;intake=function(){intakeBeforeV7();const b=document.createElement('button');b.className='btn';b.textContent='没有合适项目？新建项目';b.onclick=()=>{batch.source=$('#intakesource').value;createProject(p=>{batch.project=p.id;intake()})};$('#intakeproject').after(b)};intakeButton.onclick=()=>intake();
const newShowBeforeV7=show;show=function(v){newShowBeforeV7(v);if(v==='home'){$('#projectstrip').innerHTML=projects.map(card).join('');$('#metrics .metric b').textContent=projects.length}};
